values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'atlas-group' and v.version = '1.0.0'), 'testimonials', 'Testimonials', '{"heading":"What our clients say","items":[{"quote":"Atlas has been a dependable partner for fifteen years. Their quality never slips.","author":"Hiroshi Tanaka","role":"Procurement Head, Kanto Motors"},{"quote":"Their logistics team turned around our supply chain within a single quarter.","author":"Elena Petrova","role":"COO, Nordline Retail"},{"quote":"Professional, transparent and genuinely invested in our success.","author":"David Okoye","role":"Managing Director, Sahel Energy"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"items":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"quote":{"type":"string","minLength":1,"maxLength":2000},"author":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200}},"required":["quote","author"],"additionalProperties":false}}},"required":["items"],"additionalProperties":false}'::jsonb, 50);
