values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'atlas-group' and v.version = '1.0.0'), 'contact', 'Contact details', '{"heading":"Get in touch with Atlas Group","body":"Reach our corporate office or the right division directly.","phone":"+91 22 4000 1988","email":"corporate@example.com","address":"Atlas Tower, Bandra Kurla Complex, Mumbai","hours":"Mon – Fri · 9:30 AM – 6:30 PM"}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"body":{"type":"string","minLength":1,"maxLength":2000},"email":{"type":"string","format":"email","pattern":"^(?:[A-Za-z0-9_''+\\-]+\\.)*[A-Za-z0-9_''+\\-]*[A-Za-z0-9_+-]@(?:[A-Za-z0-9][A-Za-z0-9\\-]*\\.)+[A-Za-z]{2,}$"},"phone":{"type":"string","minLength":3,"maxLength":30,"pattern":"^[+\\d][\\d\\s()-]*$"},"address":{"type":"string","minLength":1,"maxLength":200},"hours":{"type":"string","minLength":1,"maxLength":200}},"required":["heading"],"additionalProperties":false}'::jsonb, 80);
