values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'atlas-group' and v.version = '1.0.0'), 'welcome', 'Principal''s welcome', '{"eyebrow":"Our group","title":"One group, many strengths","text":"From a single factory to a diversified group, Atlas has grown by investing patiently in people, quality and long-term partnerships. Each of our divisions runs independently, backed by shared values and group resources.","quote":"We build companies that our grandchildren will be proud of.","name":"Anand Rao","role":"Chairman","image":{"src":"/themes/atlas-group/place-1.svg","alt":"Anand Rao"},"button":{"label":"About us","href":"/about"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"quote":{"type":"string","minLength":1,"maxLength":2000},"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","name","image"],"additionalProperties":false}'::jsonb, 120);
