values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'atlas-group' and v.version = '1.0.0'), 'programs', 'Program cards', '{"eyebrow":"Our divisions","title":"Businesses that power everyday life","text":"Six divisions, one commitment to quality.","items":[{"title":"Atlas Manufacturing","tag":"Industrial","text":"Precision components for automotive and energy customers.","image":{"src":"/themes/atlas-group/scene-1.svg","alt":"Atlas Manufacturing"},"href":"/divisions"},{"title":"Atlas Logistics","tag":"Supply chain","text":"Warehousing, freight and last-mile delivery across the region.","image":{"src":"/themes/atlas-group/scene-2.svg","alt":"Atlas Logistics"},"href":"/divisions"},{"title":"Atlas Digital","tag":"Technology","text":"Cloud, data and software services for enterprises.","image":{"src":"/themes/atlas-group/scene-3.svg","alt":"Atlas Digital"},"href":"/divisions"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":9,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"tag":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"href":{"type":"string","maxLength":2048}},"required":["title","image"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 130);
