values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'atlas-group' and v.version = '1.0.0'), 'steps', 'Numbered steps', '{"eyebrow":"How it works","title":"Partnering with Atlas","text":"How we start working with new customers and partners.","items":[{"title":"Introduction","text":"Tell us about your goals and the division you are interested in."},{"title":"Assessment","text":"Our specialists review your needs and propose options."},{"title":"Agreement","text":"We agree scope, timelines and service levels."},{"title":"Delivery","text":"A dedicated account team manages the partnership."}],"button":{"label":"Contact us","href":"/contact"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":2,"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000}},"required":["title"],"additionalProperties":false}},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);
