values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'atlas-group' and v.version = '1.0.0'), 'photo-points', 'Photo with points', '{"eyebrow":"Our group","title":"Values that guide every division","text":"Our values are the reason customers and partners stay with us for decades.","image":{"src":"/themes/atlas-group/place-3.svg","alt":"Values that guide every division"},"points":[{"title":"Integrity","text":"We keep our word, in contracts and in conduct.","icon":"building"},{"title":"Quality","text":"Every product and service meets the standard we would expect.","icon":"globe"},{"title":"Responsibility","text":"We measure our impact on people and the planet.","icon":"chart"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"points":{"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"icon":{"type":"string","enum":["graduation-cap","book","flask","calendar","trophy","palette","music","users","award","shield","landmark","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["title","icon"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"imageRight":{"type":"string","enum":["yes","no"]}},"required":["title","points","image"],"additionalProperties":false}'::jsonb, 170);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'atlas-group' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"How do I become a supplier?","answer":"Send your company profile through our contact page and our procurement team will get in touch."},{"question":"Where are you located?","answer":"Our headquarters are in Mumbai, with offices and facilities in 24 countries."},{"question":"Do you have open positions?","answer":"Yes. We hire across all divisions throughout the year. Contact our people team for current roles."},{"question":"How can I reach investor relations?","answer":"Email our investor relations team through the contact page and we will reply within two working days."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'atlas-group';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'atlas-group' and c.slug in ('corporate', 'business', 'financial-services');

