insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'stackline' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Which technologies do you use?","answer":"We work with TypeScript, Java, Python, .NET, React and the major cloud platforms. We pick tools that suit your team."},{"question":"Do you sign NDAs?","answer":"Yes. We sign NDAs before any detailed discussion and follow strict data handling policies."},{"question":"Can you take over an existing project?","answer":"Yes. We start with a code and infrastructure review, then agree a transition plan."},{"question":"What are your support hours?","answer":"Our support desk runs 24/7 for managed services clients."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'stackline';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'stackline' and c.slug in ('it-company', 'business', 'corporate');

