values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'clearpath' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"What size companies do you work with?","answer":"Mostly mid-sized companies and fast-growing organisations, from 50 to 5,000 people."},{"question":"How long is an engagement?","answer":"Typical engagements run from six weeks to six months, depending on scope."},{"question":"Do you work internationally?","answer":"Yes. We have advised clients in India, the Middle East, Europe and Southeast Asia."},{"question":"How are fees structured?","answer":"We offer fixed fees for defined projects and monthly retainers for ongoing advisory."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'clearpath';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'clearpath' and c.slug in ('consulting', 'business', 'financial-services');

