values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'ledgerly' and v.version = '1.0.0'), 'steps', 'Numbered steps', '{"eyebrow":"How it works","title":"Your path to a clear plan","text":"Four steps, with no obligation until you are ready.","items":[{"title":"Free review","text":"A 30-minute call to understand your situation."},{"title":"Discovery","text":"We gather details on goals, income and assets."},{"title":"Your plan","text":"A written plan with clear, prioritised actions."},{"title":"Ongoing care","text":"Regular reviews as life and markets change."}],"button":{"label":"Book a review","href":"/contact"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":2,"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000}},"required":["title"],"additionalProperties":false}},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);
