select id, '1.0.0', 'harborguard', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"campus-hero","props":{"eyebrow":"Licensed insurance advisors","title":"Coverage that keeps your family safe","text":"Health, life, home and motor insurance from trusted insurers, with an advisor who helps you claim when you need it.","primaryButton":{"label":"Get a free quote","href":"/contact"},"secondaryButton":{"label":"View coverage","href":"/coverage"},"image":{"src":"/themes/harborguard/hero.svg","alt":"Harborguard Insurance"},"facts":[{"value":"35,000","label":"Policies managed"},{"value":"96%","label":"Claims settled"},{"value":"20+","label":"Partner insurers"},{"value":"48 hr","label":"Claim support"}]}},{"type":"quick-links","props":{"items":[{"title":"Coverage","text":"Health insurance","icon":"umbrella","href":"/coverage"},{"title":"About us","text":"Unbiased comparison","icon":"house","href":"/about"},{"title":"Stories","text":"See our work","icon":"car","href":"/stories"},{"title":"Contact","text":"Mon – Sat · 9:00 AM – 7:00 PM","icon":"heart-pulse","href":"/contact"}]}},{"type":"welcome","props":{"eyebrow":"About us","title":"We are on your side at claim time","text":"Buying insurance is easy. Claiming is where people need help. Harborguard advisors compare plans from leading insurers, explain the fine print, and stand with you through every claim.","quote":"A policy is a promise. Our job is to make sure it is kept.","name":"Mohan Krishnan","role":"Founder","image":{"src":"/themes/harborguard/place-1.svg","alt":"Mohan Krishnan"},"button":{"label":"About us","href":"/about"}}},{"type":"stats","props":{"items":[{"value":"35,000","label":"Policies managed"},{"value":"96%","label":"Claims settled"},{"value":"20+","label":"Partner insurers"},{"value":"48 hr","label":"Claim support"}]}},{"type":"programs","props":{"eyebrow":"Coverage","title":"Plans for every part of life","text":"Compare options from more than 20 insurers in one