insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'harborguard' and v.version = '1.0.0'), 'programs', 'Program cards', '{"eyebrow":"Coverage","title":"Plans for every part of life","text":"Compare options from more than 20 insurers in one place.","items":[{"title":"Health insurance","tag":"Family","text":"Cashless hospital cover for you, your family and parents.","image":{"src":"/themes/harborguard/scene-1.svg","alt":"Health insurance"},"href":"/coverage"},{"title":"Life insurance","tag":"Term","text":"Affordable term plans that protect your family''s future.","image":{"src":"/themes/harborguard/scene-2.svg","alt":"Life insurance"},"href":"/coverage"},{"title":"Motor insurance","tag":"Car & bike","text":"Comprehensive cover with fast, cashless repairs.","image":{"src":"/themes/harborguard/scene-3.svg","alt":"Motor insurance"},"href":"/coverage"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":9,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"tag":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"href":{"type":"string","maxLength":2048}},"required":["title","image"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 130);
