insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'harborguard' and v.version = '1.0.0'), 'photo-points', 'Photo with points', '{"eyebrow":"About us","title":"Why families trust Harborguard","text":"Honest advice and real help when you claim.","image":{"src":"/themes/harborguard/place-3.svg","alt":"Why families trust Harborguard"},"points":[{"title":"Unbiased comparison","text":"We compare plans across insurers, not just one.","icon":"umbrella"},{"title":"Claim assistance","text":"A dedicated advisor handles your claim paperwork.","icon":"house"},{"title":"Clear explanations","text":"We explain exclusions and waiting periods upfront.","icon":"car"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"points":{"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"icon":{"type":"string","enum":["graduation-cap","book","flask","calendar","trophy","palette","music","users","award","shield","landmark","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["title","icon"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"imageRight":{"type":"string","enum":["yes","no"]}},"required":["title","points","image"],"additionalProperties":false}'::jsonb, 170);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'harborguard' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Do you charge for advice?","answer":"No. Our advice is free for customers. We are paid by insurers, and we always disclose this."},{"question":"Can you help with an existing policy?","answer":"Yes. We can review policies you already hold and help with claims on them."},{"question":"How fast can I get covered?","answer":"Most motor, travel and term policies can be issued the same day."},{"question":"What documents do I need for a claim?","answer":"It depends on the claim. Your advisor sends you a simple checklist and helps you gather everything."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'harborguard';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'harborguard' and c.slug in ('insurance', 'financial-services');

