values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spotlight-coach' and v.version = '1.0.0'), 'contact', 'Contact details', '{"heading":"Let''s talk","body":"Book a free 20-minute discovery call or send a message about speaking.","phone":"+91 98111 22334","email":"maya@example.com","address":"Online and in Mumbai","hours":"Mon – Fri · 10:00 AM – 6:00 PM"}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"body":{"type":"string","minLength":1,"maxLength":2000},"email":{"type":"string","format":"email","pattern":"^(?:[A-Za-z0-9_''+\\-]+\\.)*[A-Za-z0-9_''+\\-]*[A-Za-z0-9_+-]@(?:[A-Za-z0-9][A-Za-z0-9\\-]*\\.)+[A-Za-z]{2,}$"},"phone":{"type":"string","minLength":3,"maxLength":30,"pattern":"^[+\\d][\\d\\s()-]*$"},"address":{"type":"string","minLength":1,"maxLength":200},"hours":{"type":"string","minLength":1,"maxLength":200}},"required":["heading"],"additionalProperties":false}'::jsonb, 80);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spotlight-coach' and v.version = '1.0.0'), 'play-hero', 'Playful hero', '{"title":"Build a personal brand that","highlight":"opens doors","text":"I help professionals and founders find their voice, grow their audience and become the obvious choice in their field.","primaryButton":{"label":"Book a discovery call","href":"/contact"},"secondaryButton":{"label":"See programmes","href":"/programmes"},"badges":[{"label":"1,200+ people coached"},{"label":"85 talks given"},{"label":"50K newsletter readers"},{"label":"4.9★ average rating"}],"image":{"src":"/themes/spotlight-coach/hero.svg","alt":"Spotlight Coach"},"smallImage":{"src":"/themes/spotlight-coach/scene-2.svg","alt":"Group programme"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"highlight":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"primaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"secondaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"badges":{"maxItems":4,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":200}},"required":["label"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"smallImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["title","badges","image"],"additionalProperties":false}'::jsonb, 90);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spotlight-coach' and v.version = '1.0.0'), 'page-hero', 'Page title with photo', '{"eyebrow":"About us","title":"From quiet expert to trusted voice","text":"You do not need to be loud. You need to be clear, consistent and generous.","image":{"src":"/themes/spotlight-coach/place-2.svg","alt":"Spotlight Coach"},"color":"mint"}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"color":{"type":"string","enum":["sun","coral","mint","grape","sky"]}},"required":["title","image"],"additionalProperties":false}'::jsonb, 100);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spotlight-coach' and v.version = '1.0.0'), 'classes', 'Class cards by age', '{"eyebrow":"Programmes","title":"Ways to work together","text":"Pick the format that fits your goals and schedule.","items":[{"title":"1:1 coaching","ages":"12 weeks","text":"Personal sessions to define your brand and build momentum.","image":{"src":"/themes/spotlight-coach/scene-1.svg","alt":"1:1 coaching"},"color":"sun"},{"title":"Group programme","ages":"8 weeks","text":"Learn alongside a small, supportive cohort.","image":{"src":"/themes/spotlight-coach/scene-2.svg","alt":"Group programme"},"color":"coral"},{"title":"Speaker training","ages":"Workshop","text":"Craft and deliver talks that people remember.","image":{"src":"/themes/spotlight-coach/scene-3.svg","alt":"Speaker training"},"color":"mint"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":8,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"ages":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"color":{"type":"string","enum":["sun","coral","mint","grape","sky"]}},"required":["title","image","color"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 110);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spotlight-coach' and v.version = '1.0.0'), 'photo-points', 'Photo and points', '{"eyebrow":"Hi, I''m Maya","title":"From quiet expert to trusted voice","text":"Ten years ago I was the best-kept secret in my industry. Learning to share my ideas changed my career. Now I help others do the same, with simple systems for content, speaking and networking.","image":{"src":"/themes/spotlight-coach/place-1.svg","alt":"From quiet expert to trusted voice"},"points":[{"title":"Clarity","text":"Know exactly what you stand for and who you serve.","icon":"mic"},{"title":"Confidence","text":"Speak and write in your own authentic voice.","icon":"target"},{"title":"Consistency","text":"A simple weekly routine that fits busy schedules.","icon":"rocket"},{"title":"Community","text":"Connect with ambitious, generous peers.","icon":"sparkles"}],"button":{"label":"About us","href":"/about"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"points":{"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["title","icon"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","points","image"],"additionalProperties":false}'::jsonb, 120);
