values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spotlight-coach' and v.version = '1.0.0'), 'day-timeline', 'Daily routine', '{"eyebrow":"How it works","title":"Your coaching journey","text":"Four stages from first call to confident presence.","items":[{"time":"Step 1","title":"Discover","text":"We define your story, strengths and audience.","icon":"mic"},{"time":"Step 2","title":"Design","text":"We shape your message and signature topics.","icon":"target"},{"time":"Step 3","title":"Show up","text":"You start publishing and speaking with support.","icon":"rocket"},{"time":"Step 4","title":"Grow","text":"We review results and scale what works.","icon":"sparkles"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":2,"maxItems":10,"type":"array","items":{"type":"object","properties":{"time":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["time","title","icon"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 130);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spotlight-coach' and v.version = '1.0.0'), 'teachers', 'Teacher circles', '{"eyebrow":"Our team","title":"The Spotlight team","members":[{"name":"Maya Kapoor","role":"Founder & Coach","image":{"src":"/themes/spotlight-coach/person-1.svg","alt":"Maya Kapoor"}},{"name":"Aditya Rao","role":"Content Strategist","image":{"src":"/themes/spotlight-coach/person-2.svg","alt":"Aditya Rao"}},{"name":"Sophie Laurent","role":"Speaking Coach","image":{"src":"/themes/spotlight-coach/person-3.svg","alt":"Sophie Laurent"}},{"name":"Nisha Patel","role":"Community Manager","image":{"src":"/themes/spotlight-coach/person-4.svg","alt":"Nisha Patel"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"fact":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spotlight-coach' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Who is coaching for?","answer":"Professionals, founders and leaders who want to be more visible in their industry."},{"question":"How much time will it take?","answer":"Plan for about two to three hours a week, including sessions."},{"question":"Do you offer payment plans?","answer":"Yes. All programmes can be paid in monthly instalments."},{"question":"Can you speak at our event?","answer":"I would love to. Send event details through the contact page."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'spotlight-coach';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'spotlight-coach' and c.slug in ('personal-branding', 'consulting', 'business');

