insert into public.theme_versions (theme_id, version, component_id, component_version, status, default_config, design_tokens, compatibility)
select id, '1.0.0', 'ashford-lane', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"campus-hero","props":{"eyebrow":"Advocates & Solicitors · Since 1979","title":"Experienced counsel when the stakes are high","text":"Ashford & Lane represents individuals and businesses in disputes, transactions and family matters, with care and discretion.","primaryButton":{"label":"Book a consultation","href":"/contact"},"secondaryButton":{"label":"Practice areas","href":"/practice-areas"},"image":{"src":"/themes/ashford-lane/hero.svg","alt":"Ashford Lane"},"facts":[{"value":"45 yrs","label":"Of practice"},{"value":"3,000+","label":"Cases handled"},{"value":"28","label":"Lawyers"},{"value":"94%","label":"Client satisfaction"}]}},{"type":"quick-links","props":{"items":[{"title":"Practice areas","text":"Corporate law","icon":"scale","href":"/practice-areas"},{"title":"About us","text":"Partner-led","icon":"briefcase","href":"/about"},{"title":"Our firm","text":"See our work","icon":"house","href":"/our-firm"},{"title":"Contact","text":"Mon – Fri · 9:30 AM – 6:30 PM","icon":"hand-heart","href":"/contact"}]}},{"type":"welcome","props":{"eyebrow":"The firm","title":"Tradition, integrity and results","text":"For more than four decades, our lawyers have combined deep legal knowledge with a genuine understanding of what clients are going through. We give honest assessments, clear fees and committed representation.","quote":"Every client deserves a lawyer who listens first and fights hard.","name":"Edward Ashford","role":"Senior Partner","image":{"src":"/themes/ashford-lane/place-1.svg","alt":"Edward Ashford"},"button":{"label":"About us","href":"/about"}}},{"type":"stats","props":{"items":[{"value":"45 yrs","label":"Of practice"},{"value":"3,000+","label":"Cases handled"},{"value":"28","label":"Lawyers"},{"value":"94%","label":"Client satisfaction"}]}},{"type":"programs","props":{"eyebrow":"Practice areas","title":"How we can help","text":"Ful