values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'ashford-lane' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Is the first consultation really free?","answer":"Yes. The first 30-minute consultation is free and completely confidential."},{"question":"How are your fees calculated?","answer":"Depending on the matter, we charge fixed fees, hourly rates or staged fees. You will always receive a written estimate."},{"question":"Do you handle cases outside the city?","answer":"Yes. We represent clients across the country and work with associate firms abroad."},{"question":"What should I bring to the first meeting?","answer":"Bring any documents related to your matter, such as contracts, notices or correspondence."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'ashford-lane';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'ashford-lane' and c.slug in ('law-firm', 'consulting');

