values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'folio' and v.version = '1.0.0'), 'quick-links', 'Quick link cards', '{"items":[{"title":"Services","text":"Brand identity","icon":"pen","href":"/services"},{"title":"About us","text":"Listening first","icon":"sparkles","href":"/about"},{"title":"Portfolio","text":"See our work","icon":"camera","href":"/portfolio"},{"title":"Contact","text":"Mon – Fri · 10:00 AM – 6:00 PM","icon":"lightbulb","href":"/contact"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"items":{"minItems":2,"maxItems":4,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["graduation-cap","book","flask","calendar","trophy","palette","music","users","award","shield","landmark","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]},"href":{"type":"string","maxLength":2048}},"required":["title","icon"],"additionalProperties":false}}},"required":["items"],"additionalProperties":false}'::jsonb, 110);
