insert into public.theme_versions (theme_id, version, component_id, component_version, status, default_config, design_tokens, compatibility)
select id, '1.0.0', 'devspace', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"play-hero","props":{"title":"I build web apps that are","highlight":"fast and fun to use","text":"Hi, I am Aarav, a full-stack developer who turns ideas into polished products with React, TypeScript and the cloud.","primaryButton":{"label":"Hire me","href":"/contact"},"secondaryButton":{"label":"See my skills","href":"/skills"},"badges":[{"label":"7 yrs of coding"},{"label":"40+ apps shipped"},{"label":"2M monthly users"},{"label":"1.2K github stars"}],"image":{"src":"/themes/devspace/hero.svg","alt":"Devspace"},"smallImage":{"src":"/themes/devspace/scene-2.svg","alt":"Backend"}}},{"type":"stats","props":{"items":[{"value":"7 yrs","label":"Of coding"},{"value":"40+","label":"Apps shipped"},{"value":"2M","label":"Monthly users"},{"value":"1.2K","label":"GitHub stars"}]}},{"type":"classes","props":{"eyebrow":"Skills","title":"What I work with","text":"Modern tools and solid engineering habits.","items":[{"title":"Frontend","ages":"React · Next.js","text":"Accessible, responsive interfaces with great performance.","image":{"src":"/themes/devspace/scene-1.svg","alt":"Frontend"},"color":"sun"},{"title":"Backend","ages":"Node · Postgres","text":"APIs, databases and background jobs that scale.","image":{"src":"/themes/devspace/scene-2.svg","alt":"Backend"},"color":"coral"},{"title":"Cloud","ages":"AWS · Vercel","text":"Infrastructure as code, CI/CD and monitoring.","image":{"src":"/themes/devspace/scene-3.svg","alt":"Cloud"},"color":"mint"}]}},{"type":"photo-points","props":{"eyebrow":"About me","title":"Curious engineer, careful builder","text":"I love the whole stack, from database design to the last pixel of a button. I care about accessibility, performance and writing code that the next developer will thank me for.","image":{"src":"/themes/devspace/place-1.svg","alt":"Curious engineer, careful builder"},"points":[{"title":"Clear updates","text":"Short written updates every day.","icon":"code"},{"title":"Tested code","text":"Automated tests for everything important.","icon":"rocket"},{"title":"Accessible","text":"Built for keyboard, screen readers and all devices.","icon":"cpu"},{"title":"Fast","text":"Performance budgets on every page.","icon":"laptop"}],"button":{"label":"About us","href":"/about"}}},{"type":"day-timeline","props":{"eyebrow":"How it works","title":"Working together","text":"A simple, transparent way to build.","items":[{"time":"Step 1","title":"Chat","text":"We discuss your idea, goals and constraints.","icon":"code"},{"time":"Step 2","title":"Plan","text":"I break the work into small, testable steps.","icon":"rocket"},{"time":"Step 3","title":"Build","text":"Weekly demos and a live preview link.","icon":"cpu"},{"time":"Step 4","title":"Launch","text":"Deployment, monitoring and handover.","icon":"laptop"}]}},{"type":"teachers","props":{"eyebrow":"Our team","title":"People I build with","members":[{"name":"Aarav Singh","role":"Developer","image":{"src":"/themes/devspace/person-1.svg","alt":"Aarav Singh"}},{"name":"Mira Das","role":"Product Designer","image":{"src":"/themes/devspace/person-2.svg","alt":"Mira Das"}},{"name":"Kenji Watanabe","role":"DevOps Engineer","image":{"src":"/themes/devspace/person-3.svg","alt":"Kenji Watanabe"}},{"name":"Sara Ahmed","role":"QA Engineer","image":{"src":"/themes/devspace/person-4.svg","alt":"Sara Ahmed"}}]}},{"type":"testimonials","props":{"heading":"What our clients say","items":[{"quote":"Aarav rebuilt our dashboard in six weeks. Load times dropped by 70%.","author":"Emily Zhang","role":"CTO, Ledgerline"},{"quote":"Great communicator and an even better engineer.","author":"Rohit Jain","role":"Product Manager, Shopkart"},{"quote":"Our app launched on time and has been rock solid since.","author":"Hana Kim","role":"Founder, Petpal"}]}},{"type":"cta","props":{"heading":"Curious engineer, careful builder","body":"Open to freelance and full-time roles","