select id, '1.0.0', 'linea', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"campus-hero","props":{"eyebrow":"Architecture and planning","title":"Spaces shaped by light, place and people","text":"Linea designs homes, workplaces and public buildings that feel generous, work beautifully and respect their surroundings.","primaryButton":{"label":"Discuss a project","href":"/contact"},"secondaryButton":{"label":"Our services","href":"/services"},"image":{"src":"/themes/linea/hero.svg","alt":"Linea Architects"},"facts":[{"value":"140","label":"Projects built"},{"value":"22 yrs","label":"In practice"},{"value":"11","label":"Design awards"},{"value":"30%","label":"Lower energy use"}]}},{"type":"quick-links","props":{"items":[{"title":"Services","text":"Residential","icon":"ruler","href":"/services"},{"title":"About us","text":"Context","icon":"building","href":"/about"},{"title":"Projects","text":"See our work","icon":"house","href":"/projects"},{"title":"Contact","text":"Mon – Fri · 9:30 AM – 6:30 PM","icon":"leaf","href":"/contact"}]}},{"type":"welcome","props":{"eyebrow":"The studio","title":"Design that starts with the site","text":"Every Linea project begins by walking the land, studying the light and listening to the people who will use the building. The result is architecture that feels as if it has always belonged.","quote":"A good building is quiet. It lets life, light and landscape take the stage.","name":"Vikram Sethi","role":"Principal Architect","image":{"src":"/themes/linea/place-1.svg","alt":"Vikram Sethi"},"button":{"label":"About us","href":"/about"}}},{"type":"stats","props":{"items":[{"value":"140","label":"Projects built"},{"value":"22 yrs","label":"In practice"},{"value":"11","label":"Design awards"},{"value":"30%","label":"Lower energy use"}]}},{"type":"programs","props":{"eyebrow":"Services","title":"From first sketch to final handover","text":"Full architectural services for private and public clients.",