values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'linea' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Do you work outside the city?","answer":"Yes. We have completed projects across India and in Sri Lanka and the UAE."},{"question":"How are fees calculated?","answer":"Fees are usually a percentage of construction cost, agreed in writing before work starts."},{"question":"Can you help with approvals?","answer":"Yes. We prepare and manage all drawings needed for statutory approvals."},{"question":"Do you design interiors too?","answer":"We offer integrated interior design so the building and interiors work as one."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'linea';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'linea' and c.slug in ('architecture', 'interior-design', 'construction');

