values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'neon-nights' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Is there an age limit?","answer":"Most shows are 21+. Some weekend matinees are open to all ages."},{"question":"Can I book a table?","answer":"Yes. Table bookings are available for groups of four or more."},{"question":"Do you host private parties?","answer":"Yes. We host parties for 30 to 800 guests. Contact our events team."},{"question":"Is there parking?","answer":"Valet parking is available every evening."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'neon-nights';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'neon-nights' and c.slug in ('entertainment', 'event-management');

