values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'daily-ledger' and v.version = '1.0.0'), 'testimonials', 'Testimonials', '{"heading":"What our clients say","items":[{"quote":"The only paper I trust to tell me what is really happening in my city.","author":"Arvind K.","role":"Reader since 2001"},{"quote":"Their investigation into water contracts changed policy. That is real journalism.","author":"Dr. Leela Nair","role":"Civic activist"},{"quote":"Clear, fair and always well written.","author":"Sameer P.","role":"Subscriber"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"items":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"quote":{"type":"string","minLength":1,"maxLength":2000},"author":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200}},"required":["quote","author"],"additionalProperties":false}}},"required":["items"],"additionalProperties":false}'::jsonb, 50);
