],"additionalProperties":false},"imageRight":{"type":"string","enum":["yes","no"]}},"required":["title","points","image"],"additionalProperties":false}'::jsonb, 170);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'wander-quarterly' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"How do I subscribe?","answer":"Choose a print or digital subscription through our contact page."},{"question":"Do you ship internationally?","answer":"Yes. Print issues ship to over 40 countries."},{"question":"Do you accept pitches?","answer":"Yes. We read every pitch and reply within three weeks."},{"question":"Can I buy back issues?","answer":"Most back issues are available while stocks last."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'wander-quarterly';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'wander-quarterly' and c.slug in ('magazine', 'blog', 'tourism');

