values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'notebook' and v.version = '1.0.0'), 'contact', 'Contact details', '{"heading":"Write to me","body":"I read every message, even if it takes me a little while to reply.","phone":"+91 98400 55667","email":"sara@example.com","address":"Written from Goa","hours":"Replies within a week"}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"body":{"type":"string","minLength":1,"maxLength":2000},"email":{"type":"string","format":"email","pattern":"^(?:[A-Za-z0-9_''+\\-]+\\.)*[A-Za-z0-9_''+\\-]*[A-Za-z0-9_+-]@(?:[A-Za-z0-9][A-Za-z0-9\\-]*\\.)+[A-Za-z]{2,}$"},"phone":{"type":"string","minLength":3,"maxLength":30,"pattern":"^[+\\d][\\d\\s()-]*$"},"address":{"type":"string","minLength":1,"maxLength":200},"hours":{"type":"string","minLength":1,"maxLength":200}},"required":["heading"],"additionalProperties":false}'::jsonb, 80);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'notebook' and v.version = '1.0.0'), 'play-hero', 'Playful hero', '{"title":"Little notes about a","highlight":"well-lived life","text":"Essays, how-tos and honest reflections on creativity, slow living and building a career you actually like.","primaryButton":{"label":"Subscribe free","href":"/contact"},"secondaryButton":{"label":"Browse topics","href":"/topics"},"badges":[{"label":"320 posts"},{"label":"18K subscribers"},{"label":"8 yrs writing"},{"label":"Weekly new posts"}],"image":{"src":"/themes/notebook/hero.svg","alt":"Notebook"},"smallImage":{"src":"/themes/notebook/scene-2.svg","alt":"Slow living"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"highlight":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"primaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"secondaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"badges":{"maxItems":4,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":200}},"required":["label"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"smallImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["title","badges","image"],"additionalProperties":false}'::jsonb, 90);
