insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'notebook' and v.version = '1.0.0'), 'classes', 'Class cards by age', '{"eyebrow":"Topics","title":"What I write about","text":"Pick a topic and make a cup of tea.","items":[{"title":"Creativity","ages":"Making","text":"Finding time and courage to make things.","image":{"src":"/themes/notebook/scene-1.svg","alt":"Creativity"},"color":"sun"},{"title":"Slow living","ages":"Home","text":"Simple routines, decluttering and calm homes.","image":{"src":"/themes/notebook/scene-2.svg","alt":"Slow living"},"color":"coral"},{"title":"Career","ages":"Work","text":"Changing paths, freelancing and finding meaning.","image":{"src":"/themes/notebook/scene-3.svg","alt":"Career"},"color":"mint"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":8,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"ages":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"color":{"type":"string","enum":["sun","coral","mint","grape","sky"]}},"required":["title","image","color"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 110);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'notebook' and v.version = '1.0.0'), 'photo-points', 'Photo and points', '{"eyebrow":"Hi, I''m Sara","title":"Writing my way through it all","text":"I started this notebook to make sense of changing careers. Years later, it is a cosy corner of the internet where thousands of readers share ideas, recipes and gentle encouragement.","image":{"src":"/themes/notebook/place-1.svg","alt":"Writing my way through it all"},"points":[{"title":"Honest","text":"Real stories, including the messy parts.","icon":"pen"},{"title":"Practical","text":"Ideas you can try this week.","icon":"coffee"},{"title":"Kind","text":"A community built on encouragement.","icon":"lightbulb"},{"title":"Ad-free","text":"No pop-ups or clutter, ever.","icon":"leaf"}],"button":{"label":"About us","href":"/about"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"points":{"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["title","icon"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","points","image"],"additionalProperties":false}'::jsonb, 120);
