values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'notebook' and v.version = '1.0.0'), 'day-timeline', 'Daily routine', '{"eyebrow":"How it works","title":"Join the notebook","text":"Become part of the community.","items":[{"time":"Step 1","title":"Subscribe","text":"Get new posts in your inbox every week.","icon":"pen"},{"time":"Step 2","title":"Read","text":"Explore the archive by topic.","icon":"coffee"},{"time":"Step 3","title":"Reply","text":"Hit reply and share your thoughts.","icon":"lightbulb"},{"time":"Step 4","title":"Share","text":"Pass a favourite post to a friend.","icon":"leaf"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":2,"maxItems":10,"type":"array","items":{"type":"object","properties":{"time":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["time","title","icon"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 130);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'notebook' and v.version = '1.0.0'), 'teachers', 'Teacher circles', '{"eyebrow":"Our team","title":"Guest writers","members":[{"name":"Sara Thomas","role":"Writer","image":{"src":"/themes/notebook/person-1.svg","alt":"Sara Thomas"}},{"name":"Ankit Rao","role":"Recipe Contributor","image":{"src":"/themes/notebook/person-2.svg","alt":"Ankit Rao"}},{"name":"Julia Brooks","role":"Book Reviewer","image":{"src":"/themes/notebook/person-3.svg","alt":"Julia Brooks"}},{"name":"Meera Paul","role":"Photographer","image":{"src":"/themes/notebook/person-4.svg","alt":"Meera Paul"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"fact":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'notebook' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Is the newsletter free?","answer":"Yes, completely free. You can unsubscribe at any time."},{"question":"Can I write a guest post?","answer":"I welcome guest posts on creativity and slow living. Send me a pitch."},{"question":"Do you accept sponsorships?","answer":"Only from small brands I genuinely use and love."},{"question":"How often do you post?","answer":"Every Tuesday, with occasional extra posts."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'notebook';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'notebook' and c.slug in ('blog', 'personal-branding', 'magazine');

