select id, '1.0.0', 'carewell', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"campus-hero","props":{"eyebrow":"Multispeciality hospital","title":"Advanced medicine with a caring heart","text":"Carewell brings together 40 specialities, modern technology and compassionate staff, with emergency care around the clock.","primaryButton":{"label":"Book an appointment","href":"/contact"},"secondaryButton":{"label":"Our departments","href":"/departments"},"image":{"src":"/themes/carewell/hero.svg","alt":"Carewell Hospital"},"facts":[{"value":"350","label":"Beds"},{"value":"120+","label":"Specialists"},{"value":"24/7","label":"Emergency"},{"value":"NABH","label":"Accredited"}]}},{"type":"quick-links","props":{"items":[{"title":"Departments","text":"Cardiology","icon":"heart-pulse","href":"/departments"},{"title":"About us","text":"Expert doctors","icon":"stethoscope","href":"/about"},{"title":"Facilities","text":"See our work","icon":"activity","href":"/facilities"},{"title":"Contact","text":"OPD Mon – Sat 8 AM – 8 PM · Emergency 24/7","icon":"baby","href":"/contact"}]}},{"type":"welcome","props":{"eyebrow":"About Carewell","title":"Healing begins with listening","text":"For over 25 years, Carewell has cared for families across the region. Our doctors take time to explain, our nurses treat every patient like family, and our technology helps us get the diagnosis right.","quote":"Every patient deserves world-class medicine and genuine kindness.","name":"Dr. Suresh Reddy","role":"Medical Director","image":{"src":"/themes/carewell/place-1.svg","alt":"Dr. Suresh Reddy"},"button":{"label":"About us","href":"/about"}}},{"type":"stats","props":{"items":[{"value":"350","label":"Beds"},{"value":"120+","label":"Specialists"},{"value":"24/7","label":"Emergency"},{"value":"NABH","label":"Accredited"}]}},{"type":"programs","props":{"eyebrow":"Departments","title":"Specialist care under one roof","text":"From routine check-ups to complex surgery.","items":[{"title":"Cardiology","tag":"Heart","text":"Heart check-ups, cath lab and cardiac surgery.","image":{"src":"/themes/carewell/scene-1.svg","alt":"Cardiology"},"href":"/departments"},{"title":"Orthopaedics","tag":"Bones & joints","text":"Joint replacement, sports injuries and spine care.","image":{"src":"/themes/carewell/scene-2.svg","alt":"Orthopaedics"},"href":"/departments"},{"title":"Paediatrics","tag":"Children","text":"Gentle care for newborns, children and teens.","image":{"src":"/themes/carewell/scene-3.svg","alt":"Paediatrics"},"href":"/departments"}]}},{"type":"testimonials","props":{"heading":"What our clients say","items":[{"quote":"The cardiology team saved my father''s life. We will always be grateful.","author":"Ramesh K.","role":"Patient''s son"},{"quote":"Clean, calm and so well organised. The nurses were wonderful.","author":"Priya S.","role":"Maternity patient"},{"quote":"Clear explanations and no surprises in the bill.","author":"Thomas J.","role":"Knee replacement patient"}]}},{"type":"cta","props":{"heading":"Healing begins with listening","body":"24/7 emergency care · Call +91 80 4000 1122","button":{"label":"Book appointment","href":"/contact"}}}]},{"title":"About","slug":"about","sections":[{"type":"page-header","props":{"eyebrow":"About us","title":"Healing begins with listening","text":"For over 25 years, Carewell has cared for families across the region. Our doctors take time to explain, our nurses treat every patient like family, and our technology helps us get ","image":{"src":"/themes/carewell/place-2.svg","alt":"Carewell Hospital"}}},{"type":"photo-points","props":{"eyebrow":"About Carewell","title":"Why patients choose Carewell","text":"Quality, safety and compassion in everything we do.","image":{"src":"/themes/carewell/place-3.svg","alt":"Why patients choose Carewell"},"points":[{"title":"Expert doctors","text":"Experienced specialists across 40 fields.","icon":"heart-pulse"},{"title":"Modern technology","text":"3T MRI