values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'greenleaf-clinic' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Do I need an appointment?","answer":"Appointments are recommended, but we keep slots free for walk-ins every day."},{"question":"Do you offer home visits?","answer":"Yes, for elderly and bedridden patients within 5 km."},{"question":"Can I get my reports online?","answer":"Yes. Lab reports are sent to your phone and email."},{"question":"Which insurance do you accept?","answer":"We accept most corporate and family health plans for outpatient care."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'greenleaf-clinic';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'greenleaf-clinic' and c.slug in ('medical-clinic', 'hospital', 'pharmacy');

