insert into public.theme_versions (theme_id, version, component_id, component_version, status, default_config, design_tokens, compatibility)
select id, '1.0.0', 'firstlight-fertility', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"campus-hero","props":{"eyebrow":"Fertility and IVF centre","title":"Your journey to parenthood, with hope and care","text":"Firstlight combines advanced reproductive medicine with warm, personal support at every step, from first tests to holding your baby.","primaryButton":{"label":"Book a consultation","href":"/contact"},"secondaryButton":{"label":"Explore treatments","href":"/treatments"},"image":{"src":"/themes/firstlight-fertility/hero.svg","alt":"Firstlight Fertility"},"facts":[{"value":"6,500+","label":"Babies born"},{"value":"68%","label":"IVF success rate"},{"value":"20 yrs","label":"Experience"},{"value":"1:1","label":"Patient coordinator"}]}},{"type":"quick-links","props":{"items":[{"title":"Treatments","text":"Fertility assessment","icon":"baby","href":"/treatments"},{"title":"About us","text":"Advanced lab","icon":"heart-pulse","href":"/about"},{"title":"Our centre","text":"See our work","icon":"hand-heart","href":"/our-centre"},{"title":"Contact","text":"Mon – Sat · 9:00 AM – 7:00 PM","icon":"stethoscope","href":"/contact"}]}},{"type":"welcome","props":{"eyebrow":"Our approach","title":"Every story is different","text":"We know how emotional fertility treatment can be. Your care team explains every option clearly, designs a plan around you and stays by your side, with counselling and support whenever you need it.","quote":"We treat people, not just test results. Hope deserves gentle hands.","name":"Dr. Meera Kulkarni","role":"Medical Director","image":{"src":"/themes/firstlight-fertility/place-1.svg","alt":"Dr. Meera Kulkarni"},"button":{"label":"About us","href":"/about"}}},{"type":"stats","props":{"items":[{"value":"6,500+","label":"Babies born"},{"value":"68%","label":"IVF success rate"},{"value":"20 yrs","label":"Experience"},{"value":"1:1","label":"Patient coordinator"}]}},{"type":"programs","props":{"eyebrow":"