insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'firstlight-fertility' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"When should we see a fertility specialist?","answer":"After a year of trying, or after six months if the woman is over 35."},{"question":"Is IVF painful?","answer":"Most steps involve only mild discomfort. Egg collection is done under light sedation."},{"question":"What does IVF cost?","answer":"Costs vary by treatment plan. We share a clear package estimate after your assessment."},{"question":"Do you offer payment plans?","answer":"Yes. We offer EMI options and multi-cycle packages."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'firstlight-fertility';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'firstlight-fertility' and c.slug in ('ivf-center', 'hospital', 'medical-clinic');

