values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'brightsmile' and v.version = '1.0.0'), 'steps', 'Numbered steps', '{"eyebrow":"How it works","title":"Your first visit","text":"Relaxed, thorough and transparent.","items":[{"title":"Book","text":"Choose a time online or by phone."},{"title":"Check-up","text":"A full exam with digital X-rays."},{"title":"Plan","text":"We explain options, timelines and costs."},{"title":"Smile","text":"Treatment at your pace, with aftercare."}],"button":{"label":"Book appointment","href":"/contact"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":2,"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000}},"required":["title"],"additionalProperties":false}},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);
