values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'pulse-fitness' and v.version = '1.0.0'), 'teachers', 'Teacher circles', '{"eyebrow":"Our team","title":"Meet the coaches","members":[{"name":"Coach Neha","role":"Founder & HIIT","image":{"src":"/themes/pulse-fitness/person-1.svg","alt":"Coach Neha"}},{"name":"Arjun Rao","role":"Strength Coach","image":{"src":"/themes/pulse-fitness/person-2.svg","alt":"Arjun Rao"}},{"name":"Maria Lopez","role":"Spin Instructor","image":{"src":"/themes/pulse-fitness/person-3.svg","alt":"Maria Lopez"}},{"name":"Vikas Sharma","role":"Boxing Coach","image":{"src":"/themes/pulse-fitness/person-4.svg","alt":"Vikas Sharma"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"fact":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'pulse-fitness' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"I am a complete beginner. Can I join?","answer":"Absolutely. Every exercise can be scaled, and coaches help you at every step."},{"question":"What should I bring?","answer":"Comfortable clothes, trainers and a water bottle. Towels are provided."},{"question":"Do you have showers?","answer":"Yes. Our changing rooms have showers and lockers."},{"question":"Can I freeze my membership?","answer":"Yes. You can pause your membership for up to two months a year."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'pulse-fitness';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'pulse-fitness' and c.slug in ('fitness', 'gym', 'yoga');

