values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'iron-yard' and v.version = '1.0.0'), 'features', 'Features', '{"heading":"Why lifters choose Iron Yard","subheading":"Proper equipment and a supportive crowd.","items":[{"title":"Pro equipment","description":"Competition racks, plates and platforms."},{"title":"Long hours","description":"Open from 5 AM to 11 PM."},{"title":"Expert trainers","description":"Certified coaches on the floor."},{"title":"No ego","description":"Respect for everyone who trains."},{"title":"Clean and safe","description":"Equipment cleaned throughout the day."},{"title":"Recovery zone","description":"Stretching area and massage guns."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"subheading":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"description":{"type":"string","minLength":1,"maxLength":2000}},"required":["title","description"],"additionalProperties":false}}},"required":["heading","items"],"additionalProperties":false}'::jsonb, 10);
