values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'iron-yard' and v.version = '1.0.0'), 'contact', 'Contact details', '{"heading":"Visit Iron Yard","body":"Drop by for a free day pass or book a tour.","phone":"+91 98220 99001","email":"train@example.com","address":"Baner Road, Pune","hours":"Every day · 5:00 AM – 11:00 PM"}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"body":{"type":"string","minLength":1,"maxLength":2000},"email":{"type":"string","format":"email","pattern":"^(?:[A-Za-z0-9_''+\\-]+\\.)*[A-Za-z0-9_''+\\-]*[A-Za-z0-9_+-]@(?:[A-Za-z0-9][A-Za-z0-9\\-]*\\.)+[A-Za-z]{2,}$"},"phone":{"type":"string","minLength":3,"maxLength":30,"pattern":"^[+\\d][\\d\\s()-]*$"},"address":{"type":"string","minLength":1,"maxLength":200},"hours":{"type":"string","minLength":1,"maxLength":200}},"required":["heading"],"additionalProperties":false}'::jsonb, 80);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'iron-yard' and v.version = '1.0.0'), 'play-hero', 'Playful hero', '{"title":"Get strong. Stay strong.","highlight":"Train here.","text":"Iron Yard has everything you need to train hard: free weights, racks, cardio and expert trainers, open early until late.","primaryButton":{"label":"Join now","href":"/contact"},"secondaryButton":{"label":"View memberships","href":"/memberships"},"badges":[{"label":"15,000 sq ft floor"},{"label":"5 AM opens daily"},{"label":"10 certified trainers"},{"label":"3,500 members"}],"image":{"src":"/themes/iron-yard/hero.svg","alt":"Iron Yard Gym"},"smallImage":{"src":"/themes/iron-yard/scene-2.svg","alt":"Annual"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"highlight":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"primaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"secondaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"badges":{"maxItems":4,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":200}},"required":["label"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"smallImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["title","badges","image"],"additionalProperties":false}'::jsonb, 90);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'iron-yard' and v.version = '1.0.0'), 'page-hero', 'Page title with photo', '{"eyebrow":"About us","title":"Built for people who love to train","text":"Strong is a skill. We will teach you, and then we will push you.","image":{"src":"/themes/iron-yard/place-2.svg","alt":"Iron Yard Gym"},"color":"mint"}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"color":{"type":"string","enum":["sun","coral","mint","grape","sky"]}},"required":["title","image"],"additionalProperties":false}'::jsonb, 100);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'iron-yard' and v.version = '1.0.0'), 'classes', 'Class cards by age', '{"eyebrow":"Memberships","title":"Plans for every goal","text":"No joining fees. Cancel anytime.","items":[{"title":"Monthly","ages":"Flexible","text":"Full gym access with no long-term contract.","image":{"src":"/themes/iron-yard/scene-1.svg","alt":"Monthly"},"color":"sun"},{"title":"Annual","ages":"Best value","text":"Twelve months of training at the lowest price.","image":{"src":"/themes/iron-yard/scene-2.svg","alt":"Annual"},"color":"coral"},{"title":"Personal training","ages":"1:1","text":"Coaching sessions tailored to your goals.","image":{"src":"/themes/iron-yard/scene-3.svg","alt":"Personal training"},"color":"mint"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":8,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"ages":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"color":{"type":"string","enum":["sun","coral","mint","grape","sky"]}},"required":["title","image","color"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 110);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'iron-yard' and v.version = '1.0.0'), 'photo-points', 'Photo and points', '{"eyebrow":"About the gym","title":"Built for people who love to train","text":"We are lifters, runners and athletes who wanted a gym with proper equipment and zero ego. Whether you are new to training or chasing a personal best, you will fit right in.","image":{"src":"/themes/iron-yard/place-1.svg","alt":"Built for people who love to train"},"points":[{"title":"Pro equipment","text":"Competition racks, plates and platforms.","icon":"dumbbell"},{"title":"Long hours","text":"Open from 5 AM to 11 PM.","icon":"activity"},{"title":"Expert trainers","text":"Certified coaches on the floor.","icon":"target"},{"title":"No ego","text":"Respect for everyone who trains.","icon":"badge"}],"button":{"label":"About us","href":"/about"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"points":{"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["title","icon"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","points","image"],"additionalProperties":false}'::jsonb, 120);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'iron-yard' and v.version = '1.0.0'), 'day-timeline', 'Daily routine', '{"eyebrow":"How it works","title":"Your training journey","text":"How we help you reach your goals.","items":[{"time":"Step 1","title":"Tour","text":"Visit the gym and meet the team.","icon":"dumbbell"},{"time":"Step 2","title":"Assess","text":"A free movement and strength check.","icon":"activity"},{"time":"Step 3","title":"Program","text":"Get a training plan matched to your goals.","icon":"target"},{"time":"Step 4","title":"Progress","text":"Regular check-ins and new targets.","icon":"badge"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":2,"maxItems":10,"type":"array","items":{"type":"object","properties":{"time":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["time","title","icon"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 130);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'iron-yard' and v.version = '1.0.0'), 'teachers', 'Teacher circles', '{"eyebrow":"Our team","title":"Our trainers","members":[{"name":"Raj Malhotra","role":"Owner & Head Coach","image":{"src":"/themes/iron-yard/person-1.svg","alt":"Raj Malhotra"}},{"name":"Simran Kaur","role":"Strength Coach","image":{"src":"/themes/iron-yard/person-2.svg","alt":"Simran Kaur"}},{"name":"Devon Brooks","role":"Conditioning Coach","image":{"src":"/themes/iron-yard/person-3.svg","alt":"Devon Brooks"}},{"name":"Ankit Yadav","role":"Nutrition Coach","image":{"src":"/themes/iron-yard/person-4.svg","alt":"Ankit Yadav"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"fact":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'iron-yard' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Is there a joining fee?","answer":"No. There are no joining fees on any plan."},{"question":"Can I try before I join?","answer":"Yes. Your first day pass is free."},{"question":"Do you have women-only hours?","answer":"Yes. We offer women-only sessions every morning."},{"question":"Is parking available?","answer":"Free parking is available for members."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'iron-yard';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'iron-yard' and c.slug in ('gym', 'fitness');

