select id, '1.0.0', 'lotus-flow', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"play-hero","props":{"title":"Find calm in a","highlight":"busy world","text":"Gentle and dynamic yoga classes, meditation and breathwork in a peaceful studio, for every body and every level.","primaryButton":{"label":"Book a class","href":"/contact"},"secondaryButton":{"label":"See classes","href":"/classes"},"badges":[{"label":"30 classes a week"},{"label":"8 teachers"},{"label":"12 yrs teaching"},{"label":"All levels welcome"}],"image":{"src":"/themes/lotus-flow/hero.svg","alt":"Lotus Flow Yoga"},"smallImage":{"src":"/themes/lotus-flow/scene-2.svg","alt":"Vinyasa flow"}}},{"type":"stats","props":{"items":[{"value":"30","label":"Classes a week"},{"value":"8","label":"Teachers"},{"value":"12 yrs","label":"Teaching"},{"value":"All","label":"Levels welcome"}]}},{"type":"classes","props":{"eyebrow":"Classes","title":"Classes for every mood","text":"Energising mornings, restful evenings.","items":[{"title":"Hatha","ages":"All levels","text":"Classic postures and breathing at a steady pace.","image":{"src":"/themes/lotus-flow/scene-1.svg","alt":"Hatha"},"color":"sun"},{"title":"Vinyasa flow","ages":"Intermediate","text":"Flowing sequences linked with breath.","image":{"src":"/themes/lotus-flow/scene-2.svg","alt":"Vinyasa flow"},"color":"coral"},{"title":"Yin","ages":"Relaxing","text":"Long, quiet holds for deep release.","image":{"src":"/themes/lotus-flow/scene-3.svg","alt":"Yin"},"color":"mint"}]}},{"type":"photo-points","props":{"eyebrow":"Our studio","title":"A peaceful place to practise","text":"Lotus Flow is a small, welcoming studio filled with natural light. Our experienced teachers offer hands-on guidance and modifications, so everyone can practise safely and joyfully.","image":{"src":"/themes/lotus-flow/place-1.svg","alt":"A peaceful place to practise"},"points":[{"title":"Inclusive","text":"Every body, age and ability welcome.","icon"