values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'velvet-salon' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Do I need to book in advance?","answer":"We recommend booking, especially for weekends and color services."},{"question":"How long does balayage take?","answer":"Usually two to three hours, depending on hair length."},{"question":"Do you offer bridal trials?","answer":"Yes. Bridal packages include a trial session."},{"question":"Which products do you use?","answer":"We use professional, cruelty-free brands suited to your hair type."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'velvet-salon';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'velvet-salon' and c.slug in ('salon', 'spa', 'fashion');

