insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'stillwater-spa' and c.slug in ('spa', 'salon', 'yoga');

-- Oakridge Academy 1.0.0
insert into public.themes (name, slug, description, category_id, status, is_featured, author_name, supported_features, preview_url)
values ('Oakridge Academy', 'oakridge', 'A traditional navy and crimson design for schools, with programmes, faculty, admissions steps and parent FAQs.',
  (select id from public.categories where slug = 'school'),
  'under_review', false, 'Lestow', '["multi-page","responsive","testimonials","gallery","contact-details"]'::jsonb,
  '/preview/themes/oakridge');

