lightbulb"},{"title":"Research culture","text":"Funded labs and student research projects.","icon":"globe"}]}},{"type":"features","props":{"heading":"What we stand for","subheading":"An outstanding education with real-world outcomes.","items":[{"title":"Expert faculty","description":"Over 300 teachers, most with doctorates."},{"title":"Strong placements","description":"Leading companies recruit on campus every year."},{"title":"Research culture","description":"Funded labs and student research projects."},{"title":"Global links","description":"Exchange programmes with partner universities."},{"title":"Vibrant campus","description":"80 clubs, sports and cultural festivals."},{"title":"Scholarships","description":"Financial support for deserving students."}]}},{"type":"stats","props":{"items":[{"value":"1952","label":"Founded"},{"value":"7,500","label":"Students"},{"value":"92%","label":"Placement rate"},{"value":"200+","label":"Recruiters"}]}},{"type":"faculty","props":{"eyebrow":"Our team","title":"College leadership","members":[{"name":"Dr. Thomas Varghese","subject":"Principal","image":{"src":"/themes/kingsbridge/person-1.svg","alt":"Dr. Thomas Varghese"}},{"name":"Dr. Kavita Rao","subject":"Dean of Academics","image":{"src":"/themes/kingsbridge/person-2.svg","alt":"Dr. Kavita Rao"}},{"name":"Prof. Imran Hussain","subject":"Head, Computer Science","image":{"src":"/themes/kingsbridge/person-3.svg","alt":"Prof. Imran Hussain"}},{"name":"Dr. Elizabeth John","subject":"Dean of Students","image":{"src":"/themes/kingsbridge/person-4.svg","alt":"Dr. Elizabeth John"}}]}},{"type":"cta","props":{"heading":"Where great minds meet","body":"Applications for 2027 intake are now open","button":{"label":"Apply now","href":"/contact"}}}]},{"title":"Programmes","slug":"programmes","sections":[{"type":"page-header","props":{"eyebrow":"Programmes","title":"Find your programme","text":"Over 40 undergraduate and postgraduate courses.","image":{"src":"/themes/kingsbridge/place-4.svg","al