insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'rankers' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Can I attend a demo class?","answer":"Yes. Book a free demo class for any course."},{"question":"Do you offer scholarships?","answer":"Students can earn up to 100% scholarship through our admission test."},{"question":"Are online classes available?","answer":"Yes. All courses are available live online."},{"question":"How are parents kept informed?","answer":"Parents receive monthly reports and can meet mentors anytime."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'rankers';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'rankers' and c.slug in ('coaching-institute', 'online-education', 'school');

