values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'learnloop' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Are the courses self-paced?","answer":"Yes. Learn at your own pace, with optional live mentor sessions."},{"question":"Do I get a certificate?","answer":"Yes. You receive a certificate after completing the final project."},{"question":"Can I try a course for free?","answer":"Every course has free preview lessons."},{"question":"Is there a refund policy?","answer":"Yes. Full refunds within seven days of purchase."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'learnloop';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'learnloop' and c.slug in ('online-education', 'coaching-institute', 'college');

