values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'common-ground' and v.version = '1.0.0'), 'features', 'Features', '{"heading":"How we work","subheading":"Transparent, accountable and community-led.","items":[{"title":"Community-led","description":"Local voices decide priorities."},{"title":"Transparent","description":"Audited accounts published every year."},{"title":"Efficient","description":"92% of funds go directly to programmes."},{"title":"Measurable","description":"We track and share our impact."},{"title":"Inclusive","description":"Programmes for everyone, especially the most vulnerable."},{"title":"Sustainable","description":"Solutions that last after we leave."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"subheading":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"description":{"type":"string","minLength":1,"maxLength":2000}},"required":["title","description"],"additionalProperties":false}}},"required":["heading","items"],"additionalProperties":false}'::jsonb, 10);
