values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'common-ground' and v.version = '1.0.0'), 'testimonials', 'Testimonials', '{"heading":"What our clients say","items":[{"quote":"Thanks to the scholarship, I became the first engineer in my village.","author":"Sunil Kumar","role":"Scholarship alumnus"},{"quote":"Volunteering with Common Ground changed how I see the world.","author":"Anika Mehta","role":"Volunteer"},{"quote":"A partner we trust completely, with clear reporting on impact.","author":"R. Krishnan","role":"CSR Head, Northstar Industries"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"items":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"quote":{"type":"string","minLength":1,"maxLength":2000},"author":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200}},"required":["quote","author"],"additionalProperties":false}}},"required":["items"],"additionalProperties":false}'::jsonb, 50);
