insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'common-ground' and v.version = '1.0.0'), 'play-hero', 'Playful hero', '{"title":"Small acts, together, create","highlight":"big change","text":"Common Ground supports education, health and livelihoods for families in rural and urban communities across India.","primaryButton":{"label":"Donate now","href":"/contact"},"secondaryButton":{"label":"Our programmes","href":"/programmes"},"badges":[{"label":"2.4L lives touched"},{"label":"180 villages"},{"label":"1,200 volunteers"},{"label":"92% funds to programmes"}],"image":{"src":"/themes/common-ground/hero.svg","alt":"Common Ground Foundation"},"smallImage":{"src":"/themes/common-ground/scene-2.svg","alt":"Health"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"highlight":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"primaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"secondaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"badges":{"maxItems":4,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":200}},"required":["label"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"smallImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["title","badges","image"],"additionalProperties":false}'::jsonb, 90);
