values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'common-ground' and v.version = '1.0.0'), 'classes', 'Class cards by age', '{"eyebrow":"Programmes","title":"Where your support goes","text":"Programmes designed with the communities we serve.","items":[{"title":"Education","ages":"Children","text":"Learning centres and scholarships for first-generation learners.","image":{"src":"/themes/common-ground/scene-1.svg","alt":"Education"},"color":"sun"},{"title":"Health","ages":"Families","text":"Mobile clinics, nutrition and maternal care.","image":{"src":"/themes/common-ground/scene-2.svg","alt":"Health"},"color":"coral"},{"title":"Livelihoods","ages":"Women","text":"Skills training and micro-enterprise support.","image":{"src":"/themes/common-ground/scene-3.svg","alt":"Livelihoods"},"color":"mint"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":8,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"ages":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"color":{"type":"string","enum":["sun","coral","mint","grape","sky"]}},"required":["title","image","color"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 110);
