values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'common-ground' and v.version = '1.0.0'), 'photo-points', 'Photo and points', '{"eyebrow":"Who we are","title":"Working with communities, not for them","text":"Since 2008, we have partnered with local leaders to run schools, health camps and skills programmes that communities shape and own.","image":{"src":"/themes/common-ground/place-1.svg","alt":"Working with communities, not for them"},"points":[{"title":"Community-led","text":"Local voices decide priorities.","icon":"hand-heart"},{"title":"Transparent","text":"Audited accounts published every year.","icon":"leaf"},{"title":"Efficient","text":"92% of funds go directly to programmes.","icon":"house"},{"title":"Measurable","text":"We track and share our impact.","icon":"globe"}],"button":{"label":"About us","href":"/about"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"points":{"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["title","icon"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","points","image"],"additionalProperties":false}'::jsonb, 120);
