values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'common-ground' and v.version = '1.0.0'), 'day-timeline', 'Daily routine', '{"eyebrow":"How it works","title":"Ways to help","text":"Everyone can make a difference.","items":[{"time":"Step 1","title":"Donate","text":"Give once or monthly to fund our programmes.","icon":"hand-heart"},{"time":"Step 2","title":"Volunteer","text":"Share your time and skills with us.","icon":"leaf"},{"time":"Step 3","title":"Fundraise","text":"Run, cycle or celebrate for a cause.","icon":"house"},{"time":"Step 4","title":"Partner","text":"CSR partnerships for lasting impact.","icon":"globe"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":2,"maxItems":10,"type":"array","items":{"type":"object","properties":{"time":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["time","title","icon"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 130);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'common-ground' and v.version = '1.0.0'), 'teachers', 'Teacher circles', '{"eyebrow":"Our team","title":"Our team","members":[{"name":"Kavya Iyer","role":"Executive Director","image":{"src":"/themes/common-ground/person-1.svg","alt":"Kavya Iyer"}},{"name":"Ramesh Yadav","role":"Programmes Head","image":{"src":"/themes/common-ground/person-2.svg","alt":"Ramesh Yadav"}},{"name":"Dr. Leena Thomas","role":"Health Lead","image":{"src":"/themes/common-ground/person-3.svg","alt":"Dr. Leena Thomas"}},{"name":"Joseph Kurian","role":"Finance Director","image":{"src":"/themes/common-ground/person-4.svg","alt":"Joseph Kurian"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"fact":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'common-ground' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Are donations tax deductible?","answer":"Yes. Donations are eligible for tax benefits under Section 80G."},{"question":"How is my donation used?","answer":"92% goes directly to programmes. Our annual report shows exactly where."},{"question":"Can I volunteer remotely?","answer":"Yes. We have online volunteering roles in teaching and design."},{"question":"Do you accept CSR funding?","answer":"Yes. We partner with companies on CSR programmes across India."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'common-ground';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'common-ground' and c.slug in ('ngo', 'event-management');

