select id, '1.0.0', 'saffron-table', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"campus-hero","props":{"eyebrow":"Regional Indian kitchen","title":"Every plate tells a story of home","text":"Saffron Table celebrates the forgotten recipes of India''s regions, cooked slowly with seasonal produce and hand-ground spices.","primaryButton":{"label":"Reserve a table","href":"/contact"},"secondaryButton":{"label":"See the menu","href":"/menu"},"image":{"src":"/themes/saffron-table/hero.svg","alt":"Saffron Table"},"facts":[{"value":"2012","label":"Since"},{"value":"120","label":"Seats"},{"value":"40+","label":"Regional dishes"},{"value":"4.8★","label":"Diner rating"}]}},{"type":"quick-links","props":{"items":[{"title":"Menu","text":"Small plates","icon":"utensils","href":"/menu"},{"title":"About us","text":"Seasonal produce","icon":"chef-hat","href":"/about"},{"title":"Gallery","text":"See our work","icon":"wine","href":"/gallery"},{"title":"Contact","text":"Lunch 12 – 3 PM · Dinner 7 – 11 PM","icon":"map-pin","href":"/contact"}]}},{"type":"welcome","props":{"eyebrow":"From our kitchen","title":"Recipes passed down, served with pride","text":"Our chef travelled across India collecting recipes from home cooks and grandmothers. Each dish on our menu is a tribute to those kitchens and the families who shared their secrets with us.","quote":"Food is memory. We want every guest to taste a little bit of home.","name":"Chef Arvind Nair","role":"Head Chef","image":{"src":"/themes/saffron-table/place-1.svg","alt":"Chef Arvind Nair"},"button":{"label":"About us","href":"/about"}}},{"type":"stats","props":{"items":[{"value":"2012","label":"Since"},{"value":"120","label":"Seats"},{"value":"40+","label":"Regional dishes"},{"value":"4.8★","label":"Diner rating"}]}},{"type":"programs","props":{"eyebrow":"Our menu","title":"Flavours from across India","text":"Seasonal menus that change with the harvest.","items":[{"title":"Small plates","ta