values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'morning-ritual' and v.version = '1.0.0'), 'contact', 'Contact details', '{"heading":"Come say hi","body":"Drop in, order ahead or ask about catering.","phone":"+91 98450 33221","email":"hello@example.com","address":"Koramangala 5th Block, Bengaluru","hours":"Every day · 6:00 AM – 9:00 PM"}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"body":{"type":"string","minLength":1,"maxLength":2000},"email":{"type":"string","format":"email","pattern":"^(?:[A-Za-z0-9_''+\\-]+\\.)*[A-Za-z0-9_''+\\-]*[A-Za-z0-9_+-]@(?:[A-Za-z0-9][A-Za-z0-9\\-]*\\.)+[A-Za-z]{2,}$"},"phone":{"type":"string","minLength":3,"maxLength":30,"pattern":"^[+\\d][\\d\\s()-]*$"},"address":{"type":"string","minLength":1,"maxLength":200},"hours":{"type":"string","minLength":1,"maxLength":200}},"required":["heading"],"additionalProperties":false}'::jsonb, 80);
