values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'morning-ritual' and v.version = '1.0.0'), 'play-hero', 'Playful hero', '{"title":"Start your day with a","highlight":"really good cup","text":"Specialty coffee roasted in small batches, fresh bakes every morning and a sunny corner to slow down.","primaryButton":{"label":"Order ahead","href":"/contact"},"secondaryButton":{"label":"See the menu","href":"/menu"},"badges":[{"label":"6 AM doors open"},{"label":"100% arabica beans"},{"label":"12 bakes daily"},{"label":"4.9★ rating"}],"image":{"src":"/themes/morning-ritual/hero.svg","alt":"Morning Ritual Cafe"},"smallImage":{"src":"/themes/morning-ritual/scene-2.svg","alt":"Cold brews"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"highlight":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"primaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"secondaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"badges":{"maxItems":4,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":200}},"required":["label"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"smallImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["title","badges","image"],"additionalProperties":false}'::jsonb, 90);
