values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'morning-ritual' and v.version = '1.0.0'), 'page-hero', 'Page title with photo', '{"eyebrow":"About us","title":"A little cafe with a big heart","text":"A great cup of coffee can turn any morning around.","image":{"src":"/themes/morning-ritual/place-2.svg","alt":"Morning Ritual Cafe"},"color":"mint"}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"color":{"type":"string","enum":["sun","coral","mint","grape","sky"]}},"required":["title","image"],"additionalProperties":false}'::jsonb, 100);
