values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'morning-ritual' and v.version = '1.0.0'), 'classes', 'Class cards by age', '{"eyebrow":"Menu","title":"Something for every craving","text":"Made fresh, served with a smile.","items":[{"title":"Espresso bar","ages":"Coffee","text":"Flat whites, cappuccinos and pour-overs.","image":{"src":"/themes/morning-ritual/scene-1.svg","alt":"Espresso bar"},"color":"sun"},{"title":"Cold brews","ages":"Iced","text":"Slow-steeped cold brew and tonics.","image":{"src":"/themes/morning-ritual/scene-2.svg","alt":"Cold brews"},"color":"coral"},{"title":"Fresh bakes","ages":"Bakery","text":"Croissants, cinnamon rolls and banana bread.","image":{"src":"/themes/morning-ritual/scene-3.svg","alt":"Fresh bakes"},"color":"mint"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":8,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"ages":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"color":{"type":"string","enum":["sun","coral","mint","grape","sky"]}},"required":["title","image","color"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 110);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'morning-ritual' and v.version = '1.0.0'), 'photo-points', 'Photo and points', '{"eyebrow":"Our story","title":"A little cafe with a big heart","text":"Morning Ritual began with one espresso machine and a dream of a cafe where everyone knows your order. We roast our own beans and bake everything fresh, every single day.","image":{"src":"/themes/morning-ritual/place-1.svg","alt":"A little cafe with a big heart"},"points":[{"title":"Roasted in house","text":"Fresh beans, roasted every week.","icon":"coffee"},{"title":"Baked daily","text":"Everything fresh from our oven.","icon":"croissant"},{"title":"Plant milks","text":"Oat, almond and soy at no extra cost.","icon":"leaf"},{"title":"Free Wi-Fi","text":"A comfy spot to work or read.","icon":"map-pin"}],"button":{"label":"About us","href":"/about"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"points":{"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["title","icon"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","points","image"],"additionalProperties":false}'::jsonb, 120);
