values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'morning-ritual' and v.version = '1.0.0'), 'day-timeline', 'Daily routine', '{"eyebrow":"How it works","title":"From bean to cup","text":"How we make your coffee special.","items":[{"time":"Step 1","title":"Source","text":"Beans from small farms in Chikmagalur.","icon":"coffee"},{"time":"Step 2","title":"Roast","text":"Small-batch roasting every week.","icon":"croissant"},{"time":"Step 3","title":"Brew","text":"Dialled in by our baristas every morning.","icon":"leaf"},{"time":"Step 4","title":"Enjoy","text":"Served just the way you like it.","icon":"map-pin"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":2,"maxItems":10,"type":"array","items":{"type":"object","properties":{"time":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["time","title","icon"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 130);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'morning-ritual' and v.version = '1.0.0'), 'teachers', 'Teacher circles', '{"eyebrow":"Our team","title":"Meet the baristas","members":[{"name":"Neel Shah","role":"Co-founder & Roaster","image":{"src":"/themes/morning-ritual/person-1.svg","alt":"Neel Shah"}},{"name":"Tara Shah","role":"Co-founder & Baker","image":{"src":"/themes/morning-ritual/person-2.svg","alt":"Tara Shah"}},{"name":"Ravi Kumar","role":"Head Barista","image":{"src":"/themes/morning-ritual/person-3.svg","alt":"Ravi Kumar"}},{"name":"Ella James","role":"Barista","image":{"src":"/themes/morning-ritual/person-4.svg","alt":"Ella James"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"fact":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'morning-ritual' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Do you have vegan options?","answer":"Yes. We have plant milks and several vegan bakes every day."},{"question":"Can I work from the cafe?","answer":"Of course. We have free Wi-Fi and plenty of plugs."},{"question":"Do you cater for events?","answer":"Yes. We cater coffee and pastries for offices and parties."},{"question":"Can I buy your beans?","answer":"Yes. Our house roasts are available in store and online."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'morning-ritual';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'morning-ritual' and c.slug in ('cafe', 'bakery', 'restaurant');

