insert into public.theme_versions (theme_id, version, component_id, component_version, status, default_config, design_tokens, compatibility)
select id, '1.0.0', 'crumb-bakery', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"play-hero","props":{"title":"Freshly baked","highlight":"happiness","text":"Sourdough, pastries and custom celebration cakes made by hand, with real butter and the best ingredients.","primaryButton":{"label":"Order a cake","href":"/contact"},"secondaryButton":{"label":"See our bakes","href":"/bakes"},"badges":[{"label":"4 AM ovens on"},{"label":"50+ daily bakes"},{"label":"3,000 cakes a year"},{"label":"4.9★ rating"}],"image":{"src":"/themes/crumb-bakery/hero.svg","alt":"Crumb Bakery"},"smallImage":{"src":"/themes/crumb-bakery/scene-2.svg","alt":"Sourdough"}}},{"type":"stats","props":{"items":[{"value":"4 AM","label":"Ovens on"},{"value":"50+","label":"Daily bakes"},{"value":"3,000","label":"Cakes a year"},{"value":"4.9★","label":"Rating"}]}},{"type":"classes","props":{"eyebrow":"Our bakes","title":"Made fresh every morning","text":"Pop in early for the best choice.","items":[{"title":"Celebration cakes","ages":"Custom","text":"Birthday, wedding and party cakes designed for you.","image":{"src":"/themes/crumb-bakery/scene-1.svg","alt":"Celebration cakes"},"color":"sun"},{"title":"Sourdough","ages":"Bread","text":"Slow-fermented loaves with a crackly crust.","image":{"src":"/themes/crumb-bakery/scene-2.svg","alt":"Sourdough"},"color":"coral"},{"title":"Pastries","ages":"Viennoiserie","text":"Croissants, pain au chocolat and danishes.","image":{"src":"/themes/crumb-bakery/scene-3.svg","alt":"Pastries"},"color":"mint"}]}},{"type":"photo-points","props":{"eyebrow":"Our story","title":"Baked by hand, every day","text":"Crumb started in a home kitchen with a sourdough starter called Bob. Today our bakers still shape every loaf by hand and decorate every cake as if it were for our own family.","image":{"src":"/themes/crumb-bakery/place-1.svg","alt":"Baked by hand, every day"},"points":[{"title":"Real butter","text":"Never margarine, never short