select id, '1.0.0', 'wayfarer', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"play-hero","props":{"title":"Your next adventure,","highlight":"perfectly planned","text":"Wayfarer designs tailor-made holidays across India and abroad, with handpicked hotels, local guides and 24/7 support on the road.","primaryButton":{"label":"Plan my trip","href":"/contact"},"secondaryButton":{"label":"View packages","href":"/packages"},"badges":[{"label":"18K happy travellers"},{"label":"60+ destinations"},{"label":"24/7 trip support"},{"label":"4.9★ reviews"}],"image":{"src":"/themes/wayfarer/hero.svg","alt":"Wayfarer Travels"},"smallImage":{"src":"/themes/wayfarer/scene-2.svg","alt":"Rajasthan royal"}}},{"type":"stats","props":{"items":[{"value":"18K","label":"Happy travellers"},{"value":"60+","label":"Destinations"},{"value":"24/7","label":"Trip support"},{"value":"4.9★","label":"Reviews"}]}},{"type":"classes","props":{"eyebrow":"Packages","title":"Popular holidays","text":"Every package can be customised.","items":[{"title":"Kerala backwaters","ages":"6 days","text":"Houseboats, tea gardens and Ayurvedic spas.","image":{"src":"/themes/wayfarer/scene-1.svg","alt":"Kerala backwaters"},"color":"sun"},{"title":"Rajasthan royal","ages":"8 days","text":"Palaces, forts and desert camps.","image":{"src":"/themes/wayfarer/scene-2.svg","alt":"Rajasthan royal"},"color":"coral"},{"title":"Bali escape","ages":"7 days","text":"Beaches, temples and rice terraces.","image":{"src":"/themes/wayfarer/scene-3.svg","alt":"Bali escape"},"color":"mint"}]}},{"type":"photo-points","props":{"eyebrow":"About us","title":"Travel the way you dream","text":"We are a team of travellers who love planning trips as much as taking them. Tell us what you love and we will design a holiday around you, with no hidden costs.","image":{"src":"/themes/wayfarer/place-1.svg","alt":"Travel the way you dream"},"points":[{"title":"Tailor-made","text":"Every itinerary built around you.","icon":"plane"},{"title":"Handpicked hotels","text":"Stays we have visited ourselves.","icon":"map-pin"},{"title":"No hidden costs","text":"One clear price for the whole trip.","icon":"mountain"},{"title":"Local guides","text":"Friendly experts at every destination.","icon":"umbrella"}],"button":{"label":"About us","href":"/about"}}},{"type":"day-timeline","props":{"eyebrow":"How it works","title":"Planning your holiday","text":"Four easy steps to your dream trip.","items":[{"time":"Step 1","title":"Dream","text":"Tell us where and how you like to travel.","icon":"plane"},{"time":"Step 2","title":"Design","text":"Receive a custom itinerary within 48 hours.","icon":"map-pin"},{"time":"Step 3","title":"Book","text":"Confirm and we handle every booking.","icon":"mountain"},{"time":"Step 4","title":"Travel","text":"Go and enjoy, with support all the way.","icon":"umbrella"}]}},{"type":"teachers","props":{"eyebrow":"Our team","title":"Your travel experts","members":[{"name":"Ananya Bhat","role":"Founder","image":{"src":"/themes/wayfarer/person-1.svg","alt":"Ananya Bhat"}},{"name":"Rohit Menon","role":"India Specialist","image":{"src":"/themes/wayfarer/person-2.svg","alt":"Rohit Menon"}},{"name":"Clara Weiss","role":"Europe Specialist","image":{"src":"/themes/wayfarer/person-3.svg","alt":"Clara Weiss"}},{"name":"Kenji Mori","role":"Asia Specialist","image":{"src":"/themes/wayfarer/person-4.svg","alt":"Kenji Mori"}}]}},{"type":"testimonials","props":{"heading":"What our clients say","items":[{"quote":"Every detail of our honeymoon was perfect.","author":"Sneha and Varun","role":"Bali"},{"quote":"The guides and hotels were fantastic. Our best family trip ever.","author":"The Kapoor family","role":"Kerala"},{"quote":"They sorted a flight change at 2 AM. Real support.","author":"David L.","role":"Switzerland"}]}},{"type":"cta","props":{"heading":"Travel the way you dream","body":"Early-bird deals on summer holidays","button":{"label":"Plan my trip","href":"/contact"}}}]},{"title":"About","slug":"about","sections":[{"type":"page-hero","props":{"eyebrow":"About us","title":"Travel the way you dream","text":"The best trips are the ones that feel made just for you.","image":{"src":"/themes/wayfarer/place-2.svg","alt":"Wayfarer Travels"},"color":"mint"}},{"type":"features","props":{"heading":"Why travel with Wayfarer","subheading":"Thoughtful planning and real support.","items":[{"title":"Tailor-made","description":"Every itinerary built around you."},{"title":"Handpicked hotels","description":"Stays we have visited ourselves."},{"title":"No hidden costs","description":"One clear price for the whole trip."},{"title":"Local guides","description":"Friendly experts at every destination."},{"title":"24/7 support","description":"Help on the phone, wherever you are."},{"title":"Easy visas","description":"We handle visa paperwork for you."}]}},{"type":"stats","props":{"items":[{"value":"18K","label":"Happy travellers"},{"value":"60+","label":"Destinations"},{"value":"24/7","label":"Trip support"},{"value":"4.9★","label":"Reviews"}]}},{"type":"photo-points","props":{"eyebrow":"Meet the founder","title":"Ananya Bhat","text":"The best trips are the ones that feel made just for you.","image":{"src":"/themes/wayfarer/person-1.svg","alt":"Ananya Bhat"},"points":[{"title":"Local guides","text":"Friendly experts at every destination.","icon":"map-pin"},{"title":"24/7 support","text":"Help on the phone, wherever you are.","icon":"mountain"},{"title":"Easy visas","text":"We handle visa paperwork for you.","icon":"umbrella"}]}}]},{"title":"Packages","slug":"packages","sections":[{"type":"page-hero","props":{"eyebrow":"Packages","title":"Popular holidays","text":"Every package can be customised.","image":{"src":"/themes/wayfarer/place-3.svg","alt":"Popular holidays"},"color":"sun"}},{"type":"classes","props":{"eyebrow":"Packages","title":"Find the right fit","items":[{"title":"Kerala backwaters","ages":"6 days","text":"Houseboats, tea gardens and Ayur