insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'bluecove' and v.version = '1.0.0'), 'classes', 'Class cards by age', '{"eyebrow":"Experiences","title":"Things to do","text":"Adventures for every kind of traveller.","items":[{"title":"Beach hopping","ages":"Relax","text":"Twelve beaches, from lively to secret coves.","image":{"src":"/themes/bluecove/scene-1.svg","alt":"Beach hopping"},"color":"sun"},{"title":"Spice trails","ages":"Culture","text":"Walk through spice farms with local growers.","image":{"src":"/themes/bluecove/scene-2.svg","alt":"Spice trails"},"color":"coral"},{"title":"Water sports","ages":"Adventure","text":"Kayaking, surfing and snorkelling.","image":{"src":"/themes/bluecove/scene-3.svg","alt":"Water sports"},"color":"mint"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":8,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"ages":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"color":{"type":"string","enum":["sun","coral","mint","grape","sky"]}},"required":["title","image","color"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 110);
