values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'bluecove' and v.version = '1.0.0'), 'teachers', 'Teacher circles', '{"eyebrow":"Our team","title":"Your local hosts","members":[{"name":"Maria D''Costa","role":"Tourism Director","image":{"src":"/themes/bluecove/person-1.svg","alt":"Maria D''Costa"}},{"name":"Joseph Fernandes","role":"Heritage Guide","image":{"src":"/themes/bluecove/person-2.svg","alt":"Joseph Fernandes"}},{"name":"Lina Pereira","role":"Food Trail Host","image":{"src":"/themes/bluecove/person-3.svg","alt":"Lina Pereira"}},{"name":"Arun Naik","role":"Adventure Guide","image":{"src":"/themes/bluecove/person-4.svg","alt":"Arun Naik"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"fact":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'bluecove' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"When is the best time to visit?","answer":"October to March has the best weather, while the monsoon brings lush green landscapes."},{"question":"How do I get there?","answer":"Bluecove is a two-hour drive from the international airport, with buses and taxis available."},{"question":"Is it family friendly?","answer":"Yes. Many beaches have lifeguards, and there are activities for all ages."},{"question":"Are there tourist help desks?","answer":"Yes. Help desks are available at major beaches and the bus station."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'bluecove';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'bluecove' and c.slug in ('tourism', 'travel-agency', 'hotel');

