values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'fresh-basket' and v.version = '1.0.0'), 'play-hero', 'Playful hero', '{"title":"Farm-fresh groceries,","highlight":"delivered fast","text":"Fruits, vegetables, dairy and pantry staples from local farms and trusted brands, delivered in under an hour.","primaryButton":{"label":"Shop now","href":"/contact"},"secondaryButton":{"label":"Browse departments","href":"/departments"},"badges":[{"label":"5,000+ products"},{"label":"40 partner farms"},{"label":"45 min delivery"},{"label":"4.8★ rating"}],"image":{"src":"/themes/fresh-basket/hero.svg","alt":"Fresh Basket"},"smallImage":{"src":"/themes/fresh-basket/scene-2.svg","alt":"Dairy and eggs"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"highlight":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"primaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"secondaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"badges":{"maxItems":4,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":200}},"required":["label"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"smallImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["title","badges","image"],"additionalProperties":false}'::jsonb, 90);
