values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'fresh-basket' and v.version = '1.0.0'), 'teachers', 'Teacher circles', '{"eyebrow":"Our team","title":"The Fresh Basket team","members":[{"name":"Manoj Agarwal","role":"Founder","image":{"src":"/themes/fresh-basket/person-1.svg","alt":"Manoj Agarwal"}},{"name":"Sunita Devi","role":"Store Manager","image":{"src":"/themes/fresh-basket/person-2.svg","alt":"Sunita Devi"}},{"name":"Ravi Teja","role":"Farm Partnerships","image":{"src":"/themes/fresh-basket/person-3.svg","alt":"Ravi Teja"}},{"name":"Ayaan Khan","role":"Delivery Lead","image":{"src":"/themes/fresh-basket/person-4.svg","alt":"Ayaan Khan"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"fact":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'fresh-basket' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"What is the minimum order?","answer":"There is no minimum order. Delivery is free over ₹499."},{"question":"Which areas do you deliver to?","answer":"We deliver within 6 km of each store."},{"question":"What if an item is not fresh?","answer":"Tell us and we will replace or refund it immediately."},{"question":"Do you accept card payments?","answer":"Yes. We accept UPI, cards and cash on delivery."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'fresh-basket';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'fresh-basket' and c.slug in ('grocery', 'e-commerce', 'bakery');

