values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'voltix' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Are all products genuine?","answer":"Yes. We are an authorised dealer and every product carries full brand warranty."},{"question":"Do you offer EMI?","answer":"Yes. No-cost EMI is available on major credit cards."},{"question":"Can I exchange my old phone?","answer":"Yes. We offer instant exchange value on old phones and laptops."},{"question":"Do you repair devices bought elsewhere?","answer":"Yes. Our service centre repairs most brands."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'voltix';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'voltix' and c.slug in ('electronics', 'e-commerce', 'it-company');

