values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'oak-oslo' and v.version = '1.0.0'), 'testimonials', 'Testimonials', '{"heading":"What our clients say","items":[{"quote":"Our dining table is the heart of our home. Beautiful craftsmanship.","author":"The Menon family","role":"Customers"},{"quote":"Custom bookshelves fitted perfectly. Worth every rupee.","author":"Aakash P.","role":"Customer"},{"quote":"Solid, beautiful and delivered exactly on time.","author":"Laura S.","role":"Customer"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"items":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"quote":{"type":"string","minLength":1,"maxLength":2000},"author":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200}},"required":["quote","author"],"additionalProperties":false}}},"required":["items"],"additionalProperties":false}'::jsonb, 50);
