values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'oak-oslo' and v.version = '1.0.0'), 'welcome', 'Principal''s welcome', '{"eyebrow":"Our workshop","title":"Made by hand, made to last","text":"Every piece begins as sustainably sourced timber and is shaped, joined and finished by our craftsmen. We use traditional joinery and natural finishes, so your furniture only gets better with age.","quote":"Good furniture should outlive trends and become part of your family''s story.","name":"Erik Lindqvist","role":"Design Director","image":{"src":"/themes/oak-oslo/place-1.svg","alt":"Erik Lindqvist"},"button":{"label":"About us","href":"/about"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"quote":{"type":"string","minLength":1,"maxLength":2000},"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","name","image"],"additionalProperties":false}'::jsonb, 120);
