values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'oak-oslo' and v.version = '1.0.0'), 'steps', 'Numbered steps', '{"eyebrow":"How it works","title":"Ordering custom furniture","text":"Your design, built by hand.","items":[{"title":"Consult","text":"Share your space, style and needs."},{"title":"Design","text":"We send drawings, wood and finish samples."},{"title":"Craft","text":"Your piece is made in our workshop."},{"title":"Deliver","text":"Free delivery and assembly at home."}],"button":{"label":"Visit showroom","href":"/contact"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":2,"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000}},"required":["title"],"additionalProperties":false}},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);
