values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'ironclad-builders' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Do you handle approvals?","answer":"Yes. We prepare drawings and manage statutory approvals with your architect."},{"question":"How do you control costs?","answer":"We provide itemised estimates and report spending against budget every month."},{"question":"Do you offer warranties?","answer":"Yes. We provide structural and workmanship warranties on every project."},{"question":"Which areas do you work in?","answer":"We work across Telangana, Andhra Pradesh and Karnataka."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'ironclad-builders';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'ironclad-builders' and c.slug in ('construction', 'real-estate', 'architecture');

