values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'torque-motors' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Can I test drive at home?","answer":"Yes. Book a home test drive and we will bring the car to you."},{"question":"Do you accept exchanges?","answer":"Yes. We evaluate your old car on the spot and offer a fair price."},{"question":"What does certified pre-owned mean?","answer":"Each car passes a 150-point inspection and comes with a warranty."},{"question":"Do you service all brands?","answer":"Our workshop services our brands and offers general service for most others."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'torque-motors';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'torque-motors' and c.slug in ('automobile', 'car-rental');

