values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'roadly' and v.version = '1.0.0'), 'play-hero', 'Playful hero', '{"title":"Hit the road in a car you","highlight":"will love","text":"Book clean, well-maintained cars by the hour, day or month, with doorstep delivery and 24/7 roadside help.","primaryButton":{"label":"Book a car","href":"/contact"},"secondaryButton":{"label":"See the fleet","href":"/fleet"},"badges":[{"label":"600+ cars"},{"label":"15 cities"},{"label":"24/7 roadside help"},{"label":"4.8★ rating"}],"image":{"src":"/themes/roadly/hero.svg","alt":"Roadly Car Rental"},"smallImage":{"src":"/themes/roadly/scene-2.svg","alt":"Sedans"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"highlight":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"primaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"secondaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"badges":{"maxItems":4,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":200}},"required":["label"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"smallImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["title","badges","image"],"additionalProperties":false}'