values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'roadly' and v.version = '1.0.0'), 'classes', 'Class cards by age', '{"eyebrow":"Our fleet","title":"A car for every trip","text":"All cars insured and serviced every month.","items":[{"title":"Hatchbacks","ages":"City","text":"Easy to park and light on fuel.","image":{"src":"/themes/roadly/scene-1.svg","alt":"Hatchbacks"},"color":"sun"},{"title":"Sedans","ages":"Comfort","text":"Spacious and smooth for long drives.","image":{"src":"/themes/roadly/scene-2.svg","alt":"Sedans"},"color":"coral"},{"title":"SUVs","ages":"Adventure","text":"Room for family, luggage and hills.","image":{"src":"/themes/roadly/scene-3.svg","alt":"SUVs"},"color":"mint"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":8,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"ages":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"color":{"type":"string","enum":["sun","coral","mint","grape","sky"]}},"required":["title","image","color"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 110);
