values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'roadly' and v.version = '1.0.0'), 'teachers', 'Teacher circles', '{"eyebrow":"Our team","title":"The Roadly team","members":[{"name":"Siddharth Rao","role":"Co-founder","image":{"src":"/themes/roadly/person-1.svg","alt":"Siddharth Rao"}},{"name":"Ayesha Thomas","role":"Head of Operations","image":{"src":"/themes/roadly/person-2.svg","alt":"Ayesha Thomas"}},{"name":"Vinod Kumar","role":"Fleet Manager","image":{"src":"/themes/roadly/person-3.svg","alt":"Vinod Kumar"}},{"name":"Ritika Shah","role":"Customer Support","image":{"src":"/themes/roadly/person-4.svg","alt":"Ritika Shah"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"fact":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'roadly' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"What documents do I need?","answer":"A valid driving licence and an ID proof. Verification takes a few minutes."},{"question":"Is fuel included?","answer":"Cars are delivered with fuel, and you return them with the same level."},{"question":"Is there a security deposit?","answer":"A small refundable deposit is collected and returned within 48 hours."},{"question":"Can I take the car to another state?","answer":"Yes. Interstate trips are allowed, with permits included in some plans."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'roadly';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'roadly' and c.slug in ('car-rental', 'travel-agency', 'automobile');

