insert into public.theme_versions (theme_id, version, component_id, component_version, status, default_config, design_tokens, compatibility)
select id, '1.0.0', 'ever-after', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"campus-hero","props":{"eyebrow":"Wedding planning and design","title":"The wedding of your dreams, without the stress","text":"Ever After plans and designs elegant weddings across India and abroad, from intimate ceremonies to grand celebrations.","primaryButton":{"label":"Plan your wedding","href":"/contact"},"secondaryButton":{"label":"Our services","href":"/services"},"image":{"src":"/themes/ever-after/hero.svg","alt":"Ever After Weddings"},"facts":[{"value":"600+","label":"Weddings planned"},{"value":"15","label":"Destinations"},{"value":"12 yrs","label":"Experience"},{"value":"5★","label":"Couple reviews"}]}},{"type":"quick-links","props":{"items":[{"title":"Services","text":"Full planning","icon":"gem","href":"/services"},{"title":"About us","text":"Personal planner","icon":"flower","href":"/about"},{"title":"Weddings","text":"See our work","icon":"party","href":"/weddings"},{"title":"Contact","text":"Mon – Sat · 10:00 AM – 7:00 PM","icon":"camera","href":"/contact"}]}},{"type":"welcome","props":{"eyebrow":"Our story","title":"Every love story deserves a beautiful celebration","text":"We are planners, designers and dreamers who love weddings. We take care of every detail, from venues and decor to guests and timelines, so you can enjoy every moment.","quote":"Our favourite moment is watching a couple simply enjoy their own wedding.","name":"Aanya Kapoor","role":"Founder & Lead Planner","image":{"src":"/themes/ever-after/place-1.svg","alt":"Aanya Kapoor"},"button":{"label":"About us","href":"/about"}}},{"type":"stats","props":{"items":[{"value":"600+","label":"Weddings planned"},{"value":"15","label":"Destinations"},{"value":"12 yrs","label":"Experience"},{"value":"5★","label":"Couple reviews"}]}},{"type":"programs","props":{"eyebrow":"Services","title":"Planning, design and more","text":"Choose full planning or the pieces you need.","i