values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spark-events' and v.version = '1.0.0'), 'testimonials', 'Testimonials', '{"heading":"What our clients say","items":[{"quote":"Our product launch trended on social media for two days.","author":"Nikhil V.","role":"Marketing Head, Zentro"},{"quote":"The smoothest offsite we have ever had. Our team still talks about it.","author":"Priya D.","role":"HR Director"},{"quote":"They turned my mum''s 60th into a night to remember.","author":"Karan M.","role":"Private client"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"items":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"quote":{"type":"string","minLength":1,"maxLength":2000},"author":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200}},"required":["quote","author"],"additionalProperties":false}}},"required":["items"],"additionalProperties":false}'::jsonb, 50);
