values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spark-events' and v.version = '1.0.0'), 'contact', 'Contact details', '{"heading":"Let''s create something amazing","body":"Tell us about your event and we will send ideas within 48 hours.","phone":"+91 22 4700 3344","email":"events@example.com","address":"Lower Parel, Mumbai","hours":"Mon – Sat · 10:00 AM – 7:00 PM"}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"body":{"type":"string","minLength":1,"maxLength":2000},"email":{"type":"string","format":"email","pattern":"^(?:[A-Za-z0-9_''+\\-]+\\.)*[A-Za-z0-9_''+\\-]*[A-Za-z0-9_+-]@(?:[A-Za-z0-9][A-Za-z0-9\\-]*\\.)+[A-Za-z]{2,}$"},"phone":{"type":"string","minLength":3,"maxLength":30,"pattern":"^[+\\d][\\d\\s()-]*$"},"address":{"type":"string","minLength":1,"maxLength":200},"hours":{"type":"string","minLength":1,"maxLength":200}},"required":["heading"],"additionalProperties":false}'::jsonb, 80);
