values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spark-events' and v.version = '1.0.0'), 'play-hero', 'Playful hero', '{"title":"We make every event","highlight":"unforgettable","text":"Corporate events, launches, conferences and celebrations, planned end to end by a creative team that sweats the small stuff.","primaryButton":{"label":"Plan an event","href":"/contact"},"secondaryButton":{"label":"Our services","href":"/services"},"badges":[{"label":"1,200+ events"},{"label":"300 corporate clients"},{"label":"50K guests hosted"},{"label":"4.9★ client rating"}],"image":{"src":"/themes/spark-events/hero.svg","alt":"Spark Events"},"smallImage":{"src":"/themes/spark-events/scene-2.svg","alt":"Product launches"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"highlight":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"primaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"secondaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"badges":{"maxItems":4,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":200}},"required":["label"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"smallImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["title","badges","image"],"additionalProperties":false}'::jsonb, 90);
