values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spark-events' and v.version = '1.0.0'), 'page-hero', 'Page title with photo', '{"eyebrow":"About us","title":"Big ideas, flawless execution","text":"Great events are planned in detail and remembered in feelings.","image":{"src":"/themes/spark-events/place-2.svg","alt":"Spark Events"},"color":"mint"}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"color":{"type":"string","enum":["sun","coral","mint","grape","sky"]}},"required":["title","image"],"additionalProperties":false}'::jsonb, 100);
