values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spark-events' and v.version = '1.0.0'), 'classes', 'Class cards by age', '{"eyebrow":"Services","title":"Events of every size","text":"From 20 guests to 20,000.","items":[{"title":"Corporate events","ages":"Business","text":"Conferences, town halls and award nights.","image":{"src":"/themes/spark-events/scene-1.svg","alt":"Corporate events"},"color":"sun"},{"title":"Product launches","ages":"Brands","text":"Launches that create buzz and headlines.","image":{"src":"/themes/spark-events/scene-2.svg","alt":"Product launches"},"color":"coral"},{"title":"Offsites","ages":"Teams","text":"Retreats with workshops and team building.","image":{"src":"/themes/spark-events/scene-3.svg","alt":"Offsites"},"color":"mint"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":8,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"ages":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"color":{"type":"string","enum":["sun","coral","mint","grape","sky"]}},"required":["title","image","color"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 110);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spark-events' and v.version = '1.0.0'), 'photo-points', 'Photo and points', '{"eyebrow":"About us","title":"Big ideas, flawless execution","text":"Spark is a team of producers, designers and planners who love bringing people together. We handle venues, production, entertainment and logistics, so your event feels effortless.","image":{"src":"/themes/spark-events/place-1.svg","alt":"Big ideas, flawless execution"},"points":[{"title":"One team","text":"Concept to clean-up, all in-house.","icon":"party"},{"title":"Creative concepts","text":"Themes and experiences guests remember.","icon":"mic"},{"title":"Trusted vendors","text":"Reliable partners in every city.","icon":"ticket"},{"title":"Clear budgets","text":"Transparent costs from day one.","icon":"gift"}],"button":{"label":"About us","href":"/about"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"points":{"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["title","icon"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","points","image"],"additionalProperties":false}'::jsonb, 120);
