values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spark-events' and v.version = '1.0.0'), 'day-timeline', 'Daily routine', '{"eyebrow":"How it works","title":"How we plan your event","text":"A clear process from idea to applause.","items":[{"time":"Step 1","title":"Brief","text":"Share your goals, guests and budget.","icon":"party"},{"time":"Step 2","title":"Concept","text":"We design the theme, flow and experience.","icon":"mic"},{"time":"Step 3","title":"Produce","text":"Vendors, venue, tech and rehearsals.","icon":"ticket"},{"time":"Step 4","title":"Showtime","text":"We run the event so you can enjoy it.","icon":"gift"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":2,"maxItems":10,"type":"array","items":{"type":"object","properties":{"time":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench"]}},"required":["time","title","icon"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 130);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spark-events' and v.version = '1.0.0'), 'teachers', 'Teacher circles', '{"eyebrow":"Our team","title":"Meet the crew","members":[{"name":"Rhea Bhatia","role":"Founder","image":{"src":"/themes/spark-events/person-1.svg","alt":"Rhea Bhatia"}},{"name":"Arjun Kapoor","role":"Head of Production","image":{"src":"/themes/spark-events/person-2.svg","alt":"Arjun Kapoor"}},{"name":"Sana Mirza","role":"Creative Director","image":{"src":"/themes/spark-events/person-3.svg","alt":"Sana Mirza"}},{"name":"Tom Hughes","role":"Operations Lead","image":{"src":"/themes/spark-events/person-4.svg","alt":"Tom Hughes"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"fact":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'spark-events' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"How far ahead should we book?","answer":"We recommend two to three months for most events, and six months for large conferences."},{"question":"Do you work outside the city?","answer":"Yes. We produce events across India and in the Middle East."},{"question":"Can you work with a tight budget?","answer":"Yes. We tailor concepts to fit your budget without losing impact."},{"question":"Do you provide event insurance?","answer":"We are fully insured and can arrange event-specific cover."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'spark-events';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'spark-events' and c.slug in ('event-management', 'wedding-planner', 'entertainment');
